<script>
  import { Zap, ArrowRight, Shield } from 'lucide-svelte';
  import { api,setCSRF } from '../api.js';
  let { complete }=$props();
  let name=$state(''),email=$state(''),password=$state(''),token=$state(''),enterprise=$state(''),busy=$state(false),error=$state('');
  async function setup(event){event.preventDefault();busy=true;error='';try{const auth=await api('/setup',{method:'POST',body:{token,name,email,password,enterprise_name:enterprise||undefined}});setCSRF(auth.csrf_token);await complete(auth);}catch(e){error=e.message;}finally{busy=false;}}
</script>
<div class="login-shell"><section class="login-story"><div class="brand"><span class="brandmark"><Zap size={25}/></span><span>V-OptimAIse<small>YOUR ENTERPRISE ASSISTANT</small></span></div><div class="login-copy"><span class="eyebrow">ONE INSTALLATION. A SHARED UNDERSTANDING.</span><h1>Make the work<br/><em>easier to follow.</em></h1><p>Set up your organization, connect your sources, and give every team the context it needs.</p></div><div class="login-footer"><Shield size={16}/>Private by design · Your data stays yours</div></section><main class="login-main"><div class="login-form"><span class="eyebrow">FIRST-RUN SETUP</span><h2>Create your installation</h2><p>This creates the first administrator. You can invite your team afterward.</p><form onsubmit={setup}><label>Setup token<input type="password" bind:value={token} required autocomplete="off"/><small class="help">Use the setup token generated by the installation script.</small></label><label>Organization name<input bind:value={enterprise} placeholder="Your organization"/></label><div class="form-grid"><label>Your name<input bind:value={name} required autocomplete="name"/></label><label>Email<input type="email" bind:value={email} required autocomplete="username"/></label></div><label>Password<input type="password" bind:value={password} required minlength="12" autocomplete="new-password"/><small class="help">At least 12 characters.</small></label>{#if error}<p class="form-error" role="alert">{error}</p>{/if}<button class="button primary wide" disabled={busy}>{busy?'Creating installation…':'Create administrator'}<ArrowRight size={17}/></button></form><p class="help">Model and connector keys are configured on the server. Missing optional integrations show their setup requirements inside the app.</p></div></main></div>
